#!/usr/bin/env python3
"""envcheck: a preflight doctor for CI containers.

Runs a series of named checks and prints an aligned table with
PASS/WARN/FAIL per check plus details. Exit code is 1 only if at
least one check FAILed (WARN does not affect the exit code).

Each check delegates to a small "probe" function (probe_*) so tests
can monkeypatch them to force any status.
"""

from __future__ import annotations

import argparse
import shutil
import socket
import subprocess
import sys
from dataclasses import dataclass
from typing import Callable, Optional

PASS = "PASS"
WARN = "WARN"
FAIL = "FAIL"

MIN_GIT = (2, 30, 0)
MIN_PYTHON = (3, 10, 0)
MIN_DISK_BYTES = 100 * 1024 * 1024  # 100 MB
MIN_NOFILE = 1024


@dataclass(frozen=True)
class CheckResult:
    name: str
    status: str  # PASS / WARN / FAIL
    details: str

    @property
    def ok(self) -> bool:
        return self.status != FAIL


# --------------------------------------------------------------------------
# Probe functions: tiny, isolated wrappers around the environment.
# Each returns a human-readable details string; they raise on absence.
# Tests monkeypatch these to force statuses deterministically.
# --------------------------------------------------------------------------


def probe_git() -> str:
    out = subprocess.run(
        ["git", "--version"], capture_output=True, text=True, timeout=10
    )
    if out.returncode != 0:
        raise RuntimeError(f"git --version exited {out.returncode}")
    return out.stdout.strip()


def probe_python() -> str:
    return f"python3 {sys.version.split()[0]}"


def probe_node() -> str:
    out = subprocess.run(
        ["node", "--version"], capture_output=True, text=True, timeout=10
    )
    if out.returncode != 0:
        raise RuntimeError(f"node --version exited {out.returncode}")
    return f"node {out.stdout.strip().lstrip('v')}"


def probe_disk(path: str) -> str:
    usage = shutil.disk_usage(path)
    return f"{usage.free} bytes free"


def probe_nofile() -> str:
    import resource

    soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    return f"soft={soft} hard={hard}"


def probe_dns(host: str) -> str:
    infos = socket.getaddrinfo(host, None)
    addr = infos[0][4][0]
    return f"{host} resolved to {addr}"


# --------------------------------------------------------------------------
# Checks: each turns a probe into a CheckResult.
# --------------------------------------------------------------------------


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for chunk in text.split("."):
        digits = "".join(c for c in chunk if c.isdigit())
        if not digits:
            break
        parts.append(int(digits))
    return tuple(parts) or (0,)


def _run(check_name: str, probe: Callable[[], str]) -> tuple[str, str]:
    """Run a probe, mapping exceptions to (FAIL-ish status placeholder, msg)."""
    try:
        return PASS, probe()
    except FileNotFoundError as exc:
        return FAIL, f"not found: {exc.filename or exc}"
    except Exception as exc:  # noqa: BLE001 - report anything as failure text
        return FAIL, str(exc)


def check_git() -> CheckResult:
    name = "git >= %s" % ".".join(map(str, MIN_GIT))
    try:
        line = probe_git()
    except Exception as exc:  # noqa: BLE001
        return CheckResult(name, FAIL, f"git unavailable: {exc}")
    version_str = line.split()[-1] if line else ""
    got = _version_tuple(version_str)
    if got >= MIN_GIT:
        return CheckResult(name, PASS, line.strip())
    return CheckResult(name, FAIL, f"{line.strip()} (need >={'.'.join(map(str, MIN_GIT))})")


def check_python() -> CheckResult:
    name = "python3 >= %s" % ".".join(map(str, MIN_PYTHON))
    version = "{}.{}.{}".format(*sys.version_info[:3])
    got = sys.version_info[:3]
    if got >= MIN_PYTHON:
        return CheckResult(name, PASS, f"python3 {version}")
    return CheckResult(
        name, FAIL, f"python3 {version} (need >={'.'.join(map(str, MIN_PYTHON))})"
    )


def check_node() -> CheckResult:
    name = "node present"
    try:
        line = probe_node()
    except FileNotFoundError:
        return CheckResult(name, WARN, "node not found in PATH")
    except Exception as exc:  # noqa: BLE001
        return CheckResult(name, FAIL, f"node unusable: {exc}")
    return CheckResult(name, PASS, line.strip())


def check_disk(path: str) -> CheckResult:
    name = f"free disk >= {MIN_DISK_BYTES // (1024 * 1024)}MB at {path}"
    try:
        usage = shutil.disk_usage(path)
    except Exception as exc:  # noqa: BLE001
        return CheckResult(name, FAIL, str(exc))
    mb = usage.free / (1024 * 1024)
    details = f"{mb:.1f} MB free on {usage.fstype or 'fs'}".rstrip()
    if usage.free >= MIN_DISK_BYTES:
        return CheckResult(name, PASS, details)
    return CheckResult(name, FAIL, details)


def check_nofile() -> CheckResult:
    name = f"ulimit -n >= {MIN_NOFILE}"
    import resource

    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except Exception as exc:  # noqa: BLE001
        return CheckResult(name, FAIL, str(exc))
    details = f"soft={soft} hard={hard}"
    if soft == resource.RLIM_INFINITY or soft >= MIN_NOFILE:
        return CheckResult(name, PASS, details)
    return CheckResult(name, FAIL, details)


def check_dns(host: str = "pypi.org") -> CheckResult:
    name = f"DNS resolves {host}"
    try:
        infos = socket.getaddrinfo(host, None)
        addr = infos[0][4][0]
    except Exception as exc:  # noqa: BLE001
        # Network is optional in CI sandboxes: degrade to WARN, not FAIL.
        return CheckResult(name, WARN, f"unresolvable: {exc}")
    return CheckResult(name, PASS, f"{host} -> {addr}")


CHECKS: list[tuple[str, Callable[[argparse.Namespace], CheckResult]]] = []


def run_all(args: argparse.Namespace) -> list[CheckResult]:
    return [
        check_git(),
        check_python(),
        check_node(),
        check_disk(args.path),
        check_nofile(),
        check_dns(args.host),
    ]


# --------------------------------------------------------------------------
# Rendering + CLI
# --------------------------------------------------------------------------


def render_table(results: list[CheckResult]) -> str:
    headers = ("STATUS", "CHECK", "DETAILS")
    rows = [(r.status, r.name, r.details) for r in results]
    widths = [
        max(len(h), *(len(row[i]) for row in rows)) for i, h in enumerate(headers)
    ]

    def fmt(cells: tuple[str, ...]) -> str:
        return "  ".join(
            cell.ljust(w) if i < len(cells) - 1 else cell
            for i, (cell, w) in enumerate(zip(cells, widths))
        ).rstrip()

    lines = [fmt(headers), fmt(tuple("-" * w for w in widths))]
    lines.extend(fmt(row) for row in rows)

    counts = {s: sum(1 for r in results if r.status == s) for s in (PASS, WARN, FAIL)}
    summary = ", ".join(f"{counts[s]} {s}" for s in (PASS, WARN, FAIL))
    lines.append("")
    lines.append(f"summary: {summary} ({len(results)} checks)")
    return "\n".join(lines)


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(prog="envcheck", description=__doc__)
    parser.add_argument("--path", default=".", help="path for the disk check")
    parser.add_argument("--host", default="pypi.org", help="host for the DNS check")
    args = parser.parse_args(argv)

    results = run_all(args)
    print(render_table(results))

    failed = [r for r in results if not r.ok]
    if failed:
        names = ", ".join(r.name for r in failed)
        print(f"\nFAILED checks: {names}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

